-- =====================================================================
-- P2 DEMO DATASET - replaces the ad-hoc sample data with 7 curated,
-- internally-consistent scenarios that exercise every screen and every
-- savings type / workflow stage. Also TIGHTENS calculation_status.
-- =====================================================================
-- Generated by scratchpad/gen_seed.py. Idempotent: TRUNCATEs the sample
-- transactional + dimension tables (organizations & profiles are kept),
-- then reinserts. A full JSON backup of the prior data lives at
-- sample-data-backup-2026-07-26.json (repo root, parent dir).
--
-- Amounts are full-period savings totals; the app (lib/savings) prorates
-- them across calendar years. gross_savings_amount is THE reported total;
-- cost_reduction_amount / cost_avoidance_amount are the hard/soft split
-- (each scenario lands wholly in one), so both reconcile to the total.
-- =====================================================================

begin;

-- 1) Clear the sample data (children first via CASCADE). org + profile kept.
truncate table
  public.realization_periods, public.savings_calculation_lines, public.savings_calculations,
  public.award_lines, public.awards, public.supplier_offer_lines, public.supplier_offers,
  public.baseline_lines, public.baselines, public.event_scope_lines, public.sourcing_events,
  public.cost_centers, public.suppliers, public.business_units, public.categories
  restart identity cascade;

-- 2) Dimensions



-- 3) Sourcing events

-- 4) Scope lines (2 per event)

-- 5) Baselines (one official baseline per event)

-- 6) Supplier offers (2 per event; the winning offer flagged selected)

-- 7) Awards (one per event)

-- 8) Savings calculations (one per event) - drives dashboard/savings/reports

-- 9) Realization periods - Packaging on-track, Freight with leakage

-- 10) Line-level detail for the Packaging scenario (so detail tabs aren't empty)



-- 11) Tighten calculation_status: drop the permissive original constraint
--     (which allowed BOTH the canonical set AND legacy Draft/Submitted/
--     Approved/Rejected) and replace with the strict 4-value canonical set.
alter table public.savings_calculations drop constraint if exists savings_calculations_calculation_status_check;
alter table public.savings_calculations drop constraint if exists chk_calculation_status;
alter table public.savings_calculations add constraint chk_calculation_status
  check (calculation_status in ('identified','negotiated','contracted','realized'));

-- award_status already has awards_award_status_check
--   (Recommended/Approved/Rejected/On Hold); the seed conforms, no change needed.

commit;

