  ('00000020-0000-4000-8000-000000000001', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Corrugated Packaging - Competitive Rebid', 'Competitive RFP across 4 converters. Awarded to Continental at 15% below incumbent on a 3-year deal.', 'Competitive Rebid', 'RFP', '000000ca-0000-4000-8000-000000000001', '000000b0-0000-4000-8000-000000000004', '00000050-0000-4000-8000-000000000001', '00000050-0000-4000-8000-000000000002', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Realized', 'USD', 1, '2025-10-01', '2025-10-01', '2025-10-01', '2028-09-30', 'Gross Savings', 'Sourcing', 'Sarah Chen', 'Hard cost reduction, fully realized. 3-year contract.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000002', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'CRM Platform Renewal - CloudCRM', 'Renewal where the vendor sought a 15% uplift. Negotiated to 3%, avoiding $450k of increase.', 'Renewal', 'RFP', '000000ca-0000-4000-8000-000000000002', '000000b0-0000-4000-8000-000000000001', '00000050-0000-4000-8000-000000000003', '00000050-0000-4000-8000-000000000003', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Contracted', 'USD', 1, '2026-01-01', '2026-01-01', '2026-01-01', '2026-12-31', 'Gross Savings', 'Sourcing', 'John Davis', 'Cost avoidance = the price increase we negotiated away.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000003', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'MRO Supplies - Demand Reduction', 'Consumption controls and reorder-point tuning cut MRO demand 22% without a price change.', 'Demand Reduction', 'RFP', '000000ca-0000-4000-8000-000000000003', '000000b0-0000-4000-8000-000000000002', '00000050-0000-4000-8000-000000000004', '00000050-0000-4000-8000-000000000004', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Contracted', 'USD', 1, '2026-03-01', '2026-03-01', '2026-03-01', '2027-02-28', 'Gross Savings', 'Sourcing', 'Lisa Park', 'Demand reduction - spend fell because we consumed less.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000004', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Freight & Logistics - Competitive Rebid', 'Rebid freight to BlueOcean, improving total cost of ownership 12% including accessorials and detention.', 'Competitive Rebid', 'RFP', '000000ca-0000-4000-8000-000000000004', '000000b0-0000-4000-8000-000000000002', '00000050-0000-4000-8000-000000000005', '00000050-0000-4000-8000-000000000006', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Realized', 'USD', 1, '2026-01-01', '2026-01-01', '2026-01-01', '2028-12-31', 'Gross Savings', 'Sourcing', 'Mike Rodriguez', 'TCO improvement with realization tracking - some leakage vs plan.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000005', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Payment Terms Extension - MegaSupplier', 'Extended payment terms from Net-30 to Net-60 on $6M annual spend; working-capital benefit at 4% cost of capital.', 'Payment Terms', 'RFP', '000000ca-0000-4000-8000-000000000005', '000000b0-0000-4000-8000-000000000003', '00000050-0000-4000-8000-000000000007', '00000050-0000-4000-8000-000000000007', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Contracted', 'USD', 1, '2026-05-01', '2026-05-01', '2026-05-01', '2027-04-30', 'Gross Savings', 'Sourcing', 'Sarah Chen', 'Working capital - financing benefit from extended terms, no unit-price change.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000006', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Marketing Agency - Competitive Rebid', 'In-market rebid of creative agency services. Catalyst is the front-runner at 15% below incumbent; not yet signed.', 'Competitive Rebid', 'RFP', '000000ca-0000-4000-8000-000000000006', '000000b0-0000-4000-8000-000000000003', '00000050-0000-4000-8000-000000000008', '00000050-0000-4000-8000-000000000009', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Negotiation', 'USD', 1, '2026-10-01', '2026-10-01', '2026-10-01', '2027-09-30', 'Gross Savings', 'Sourcing', 'Lisa Park', 'In-flight (negotiated) - demonstrates pipeline vs realized.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44'),
  ('00000020-0000-4000-8000-000000000007', '27a0b547-c58b-4404-b2e9-cf5bb40893d6', 'Lab Instruments - Net-New Purchase', 'First-time purchase of lab instrumentation. Competitive quotes drove a 15% avoidance vs the opening bid.', 'Net New Purchase', 'RFP', '000000ca-0000-4000-8000-000000000007', '000000b0-0000-4000-8000-000000000004', null, '00000050-0000-4000-8000-000000000010', 'c9b10017-4a74-479f-a908-c8bc91885d44', 'Scoped', 'USD', 1, null, null, null, null, 'Gross Savings', 'Sourcing', 'John Davis', 'Net-new, no incumbent, undated - demonstrates the ''unscheduled'' surfacing.', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44', now(), 'c9b10017-4a74-479f-a908-c8bc91885d44');
